#!/usr/bin/env bash
# C2970's host step (the operator, 2026-11-10: "Severity follows impact on service, not
# 'something broke'… Fix it in the provisioned Grafana alert rule (its severity label), not by
# overriding it in Mercury's display"): the telemetry rules regenerated by
# scripts/nmas-telemetry-rules, which now labels each rule `severity: warning`, and installed.
# Until it runs, Grafana's rules carry no severity label and Needs attention draws a lost
# stream critical, as before. This step:
#   1. regenerates the rules into a fresh folder, and refuses unless they hold exactly the
#      installed file's streams (no stream gained or lost) and every rule carries
#      `severity: warning`;
#   2. takes a dated copy of the installed file, installs the regenerated one and restarts
#      Grafana, proves Grafana answers and runs every rule it ran before.
# A failure puts the dated copy back and restarts Grafana again.
# A firing lost-stream alert begins again under its new labels: Grafana keeps an alert by its
# labels, so the row's "since" restarts at the first evaluation after the restart.
# Run on the NMAS host, as the operator's own user (sudo asked for the copy and the install):
#     bash <checkout>/scripts/host-steps/c2970-telemetry-severity.sh
. "$(dirname "$0")/lib.sh"

PY=${NMAS_PY:-/opt/mercury-venv/bin/python}
RULES="cd '$CHECKOUT' && '$PY' scripts/nmas-grafana-rules"
TEL="cd '$CHECKOUT' && '$PY' scripts/nmas-telemetry-rules"
DIR=/etc/grafana/provisioning/alerting
STAMP=$(date -u +%Y%m%dT%H%M%SZ)
COPY=/var/backups/grafana/c2970-$STAMP
WORK=$(mktemp -d)
echo "== the dated copy goes to $COPY"

plan "run as the operator's own user, not root" \
     "the regenerated telemetry rules hold exactly the installed streams" \
     "every regenerated rule is labelled severity warning" \
     "the dated copy reads back the same as the installed rules" \
     "Grafana answers again after the restart" \
     "every live rule is as before" \
     "the installed rules are labelled severity warning, every one"

not_root
step "every live rule, recorded before" \
    "$RULES list | cut -f1 | sort > '$WORK/rules.before' && wc -l < '$WORK/rules.before'"
step "regenerate the telemetry rules from the committed goldens" \
    "$TEL --out '$WORK/nmas-telemetry.yaml'"
check "the regenerated telemetry rules hold exactly the installed streams" eq "" \
    "diff <(grep -oE 'nmas-tel-[A-Za-z0-9_.-]+' '$DIR/nmas-telemetry.yaml' | sort -u) \
          <(grep -oE 'nmas-tel-[A-Za-z0-9_.-]+' '$WORK/nmas-telemetry.yaml' | sort -u)"
check "every regenerated rule is labelled severity warning" eq "ok" \
    "r=\$(grep -cE 'uid: nmas-tel-' '$WORK/nmas-telemetry.yaml'); \
     s=\$(grep -cE '^ +severity: warning\$' '$WORK/nmas-telemetry.yaml'); \
     [ \"\$r\" -gt 0 ] && [ \"\$r\" = \"\$s\" ] && echo ok || echo \"\$s of \$r\""

step "a fresh dated copy of the installed rules (root's, mode 700)" \
    "sudo install -d -m 700 '$COPY' && sudo cp -a '$DIR/nmas-telemetry.yaml' '$COPY/'"
check "the dated copy reads back the same as the installed rules" rc0 0 \
    "sudo cmp '$DIR/nmas-telemetry.yaml' '$COPY/nmas-telemetry.yaml'"

ON_FAIL="sudo install -m 0644 '$COPY/nmas-telemetry.yaml' '$DIR/nmas-telemetry.yaml' && \
         sudo systemctl restart grafana-server"
ON_FAIL_WHAT="the telemetry rules put back from the dated copy, Grafana restarted"
step "install the regenerated telemetry rules, then restart Grafana" \
    "sudo install -m 0644 '$WORK/nmas-telemetry.yaml' '$DIR/nmas-telemetry.yaml' && \
     sudo systemctl restart grafana-server"
check "Grafana answers again after the restart" re '^[0-9]+$' \
    "for i in \$(seq 1 60); do n=\$($RULES count 2>/dev/null) && [[ \"\$n\" =~ ^[0-9]+\$ ]] && { echo \$n; exit 0; }; sleep 2; done; echo 'no answer in 120 s'"
check "every live rule is as before" eq "" \
    "$RULES list | cut -f1 | sort | diff '$WORK/rules.before' -"
check "the installed rules are labelled severity warning, every one" eq "ok" \
    "r=\$(grep -cE 'uid: nmas-tel-' '$DIR/nmas-telemetry.yaml'); \
     s=\$(grep -cE '^ +severity: warning\$' '$DIR/nmas-telemetry.yaml'); \
     [ \"\$r\" -gt 0 ] && [ \"\$r\" = \"\$s\" ] && echo ok || echo \"\$s of \$r\""
ON_FAIL=""
echo "== the dated copy: $COPY"
summary
